def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.1 * bins
    score = -np.abs(remaining - target_buffer)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_remaining = 0.15 * bins
    deviation = np.abs(remaining - optimal_remaining)
    score = -deviation
    return np.where(remaining < 0, -np.inf, score)
